WITH scored AS (SELECT id, email, signup_date, is_active, AVG(age) OVER (PARTITION BY city ORDER BY age, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS age_avg_2, LAST_VALUE(credit_limit, TRUE) OVER (PARTITION BY country ORDER BY credit_limit, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_credit_limit, PERCENT_RANK() OVER (PARTITION BY country, city ORDER BY credit_limit NULLS FIRST) AS credit_limit_percent_rank, NTILE(5) OVER (PARTITION BY city ORDER BY credit_limit, id) AS credit_limit_bucket FROM customers) SELECT id, email, signup_date, is_active, age_avg_2, credit_limit_percent_rank, credit_limit_bucket FROM scored
